//
// Doctor registration wizard. Uses the same glass sliding layout as the family-head
// and adult-member wizard in AuthPage (commercial-auth.css) so all three registration
// paths look alike. Role was chosen on /register; Role links back there.
// API contract unchanged: multipart POST /auth/register/doctor.

import { useState } from 'react'
import type { FormEvent } from 'react'
import { Navigate, useNavigate } from 'react-router-dom'
import { z } from 'zod'

import { useAppDispatch, useAppSelector } from '../../store/hooks'
import { completeRegistration } from '../../store/slices/authSlice'
import { AuthStepper, type StepDef } from '../../components/auth/AuthStepper'
import { RegistrationReview, type ReviewSection } from '../../components/auth/RegistrationReview'
import loginBg from '../../assets/Loging.webp'
import registerBg from '../../assets/Register.webp'

import '../../styles/commercial-auth.css'
import '../../styles/doctor-register.css'

const districts = ['Ampara', 'Anuradhapura', 'Badulla', 'Batticaloa', 'Colombo', 'Galle', 'Gampaha', 'Hambantota', 'Jaffna', 'Kalutara', 'Kandy', 'Kegalle', 'Kilinochchi', 'Kurunegala', 'Mannar', 'Matale', 'Matara', 'Monaragala', 'Mullaitivu', 'Nuwara Eliya', 'Polonnaruwa', 'Puttalam', 'Ratnapura', 'Trincomalee', 'Vavuniya'] as const
const languageOptions = ['Sinhala', 'Tamil', 'English'] as const
const allowedLicenceTypes = ['application/pdf', 'image/png', 'image/jpeg']
const maxLicenceBytes = 5 * 1024 * 1024

// ── Validation schemas ────────────────────────────────────────────────────────

const accountSchema = z.object({
  displayName: z.string().trim().min(1, 'Enter your full name.').max(120, 'Name is too long.'),
  email:       z.string().email('Enter a valid email address.'),
  password:    z.string().min(12, 'Password must be at least 12 characters.').max(128),
  confirm:     z.string().min(1, 'Confirm your password.'),
}).refine((d) => d.password === d.confirm, {
  message: 'Passwords do not match.',
  path: ['confirm'],
})

const professionalSchema = z.object({
  registrationNumber: z.string().trim().min(4, 'Enter your registration number (min 4 characters).').max(30),
  specialty:          z.string().trim().max(120).optional(),
  hospitalClinic:     z.string().trim().max(200).optional(),
  phoneNumber:        z.string().trim().max(20).optional(),
})

// Step 0 is the role chosen on /register — shown as done so the stepper matches the other wizards.
const STEPS: StepDef[] = [
  { label: 'Role' },
  { label: 'Account' },
  { label: 'Professional' },
  { label: 'Practice' },
  { label: 'Review' },
]

const TITLES = ['', 'Create your account', 'Professional details', 'Practice & licence', 'Review & submit']

const PasswordEye = ({ show, toggle }: { show: boolean; toggle: () => void }) => (
  <button type="button" aria-label={show ? 'Hide password' : 'Show password'} onClick={toggle} className="doc-reg-eye">
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      {show ? (
        <><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" /><circle cx="12" cy="12" r="3" /></>
      ) : (
        <><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" /><line x1="1" y1="1" x2="23" y2="23" /></>
      )}
    </svg>
  </button>
)

function issuesToErrors(issues: z.ZodIssue[]) {
  const errs: Record<string, string> = {}
  for (const issue of issues) {
    const key = String(issue.path[0] ?? 'form')
    if (!errs[key]) errs[key] = issue.message
  }
  return errs
}

// ── Component ─────────────────────────────────────────────────────────────────

export function DoctorRegisterPage() {
  const dispatch = useAppDispatch()
  const navigate = useNavigate()

  const { isAuthenticated, user, status: authStatus, error: authError } = useAppSelector((s) => s.auth)

  const [step, setStep] = useState(1)

  // Account
  const [displayName, setDisplayName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [showPassword, setShowPassword] = useState(false)

  // Professional
  const [registrationNumber, setRegistrationNumber] = useState('')
  const [specialty, setSpecialty] = useState('')
  const [hospitalClinic, setHospitalClinic] = useState('')
  const [phoneNumber, setPhoneNumber] = useState('')

  // Practice & licence
  const [practiceCity, setPracticeCity] = useState('')
  const [district, setDistrict] = useState('')
  const [languages, setLanguages] = useState<string[]>(['English'])
  const [licenseDocument, setLicenseDocument] = useState<File | null>(null)

  const [acceptTerms, setAcceptTerms] = useState(false)
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [apiError, setApiError] = useState('')
  const [submitting, setSubmitting] = useState(false)

  if (isAuthenticated) {
    return <Navigate to={user?.role === 'DOCTOR' ? '/doctor-status' : '/dashboard'} replace />
  }

  function clearErrors() {
    setFieldErrors({})
    setApiError('')
  }

  function validateStep(current: number): Record<string, string> {
    if (current === 1) {
      const r = accountSchema.safeParse({ displayName, email, password, confirm })
      return r.success ? {} : issuesToErrors(r.error.issues)
    }
    if (current === 2) {
      const r = professionalSchema.safeParse({ registrationNumber, specialty, hospitalClinic, phoneNumber })
      return r.success ? {} : issuesToErrors(r.error.issues)
    }
    if (current === 3) {
      const errs: Record<string, string> = {}
      if (!practiceCity.trim()) errs.practiceCity = 'Enter your practice city.'
      else if (practiceCity.trim().length > 80) errs.practiceCity = 'City must be 80 characters or fewer.'
      if (!districts.includes(district as typeof districts[number])) errs.district = 'Choose a district.'
      if (languages.length < 1 || languages.length > 3) errs.languages = 'Choose 1–3 languages.'
      if (!licenseDocument) errs.licenseDocument = 'Upload a PDF, PNG or JPEG licence document (up to 5 MB).'
      else if (!allowedLicenceTypes.includes(licenseDocument.type)) errs.licenseDocument = 'Licence must be a PDF, PNG or JPEG file.'
      else if (licenseDocument.size > maxLicenceBytes) errs.licenseDocument = 'Licence must be 5 MB or smaller.'
      return errs
    }
    return {}
  }

  function handleNext() {
    clearErrors()
    const errs = validateStep(step)
    if (Object.keys(errs).length) {
      setFieldErrors(errs)
      setApiError('Check the highlighted details.')
      return
    }
    setStep((s) => s + 1)
  }

  function handleBack() {
    clearErrors()
    if (step === 1) navigate('/register')
    else setStep((s) => s - 1)
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (step < STEPS.length - 1) { handleNext(); return }
    clearErrors()
    if (!acceptTerms) {
      setFieldErrors({ acceptTerms: 'Accept the terms and privacy notice to continue.' })
      setApiError('Check the highlighted details.')
      return
    }
    if (!licenseDocument) { setStep(3); setFieldErrors({ licenseDocument: 'Upload a PDF, PNG or JPEG licence document (up to 5 MB).' }); return }

    setSubmitting(true)
    try {
      const form = new FormData()
      form.append('fullName', displayName.trim()); form.append('email', email.trim()); form.append('mobileNumber', phoneNumber.trim())
      form.append('password', password); form.append('confirmPassword', confirm); form.append('registrationNumber', registrationNumber.trim())
      form.append('specialization', specialty.trim()); form.append('hospitalClinic', hospitalClinic.trim()); form.append('practiceCity', practiceCity.trim())
      form.append('district', district); languages.forEach((language) => form.append('languages', language))
      form.append('acceptTerms', 'true'); form.append('licenseDocument', licenseDocument)
      const result = await dispatch(completeRegistration({ path: '/auth/register/doctor', body: form }))
      if (!completeRegistration.fulfilled.match(result)) { setApiError(result.payload?.message ?? 'Registration failed.'); return }
      navigate('/doctor-status', { replace: true })
    } finally {
      setSubmitting(false)
    }
  }

  const isLoading = authStatus === 'loading' || submitting
  const isFinalStep = step === STEPS.length - 1
  const fieldError = (field: string) => fieldErrors[field] && (
    <p role="alert" data-field-error className="doc-reg-error">{fieldErrors[field]}</p>
  )

  const reviewSections: ReviewSection[] = [
    { title: 'Account', step: 1, rows: [['Full name', displayName], ['Email', email]] },
    { title: 'Professional', step: 2, rows: [['SLMC registration', registrationNumber], ['Specialization', specialty], ['Hospital / clinic', hospitalClinic], ['Phone', phoneNumber]] },
    { title: 'Practice', step: 3, rows: [['City', practiceCity], ['District', district], ['Languages', languages.join(', ')], ['Licence', licenseDocument?.name ?? '']] },
  ]

  return (
    <main aria-label="Doctor registration" className="auth-page-root mode-register" style={{ backgroundImage: `url(${registerBg})` }}>
      <div className="auth-overlay"></div>

      <div className="auth-main-container">
        <div className="auth-text-panel auth-text-left" style={{ backgroundImage: `url(${loginBg})`, backgroundSize: 'cover', backgroundPosition: 'center' }}>
          <div className="auth-text-overlay"></div>
          <div className="doc-reg-hero">
            <h2 className="doc-reg-hero-title">Join as a<br />Clinician</h2>
            <p className="doc-reg-hero-text">
              Register your professional profile with FamilyVeda. Your SLMC registration and licence are reviewed by an administrator before clinical access is enabled.
            </p>
            <button type="button" className="auth-mode-switch-btn" onClick={() => navigate('/login')} style={{ marginTop: '48px' }}>
              Already a Member? Sign In <span className="switch-arrow right-arrow">→</span>
            </button>
          </div>
        </div>

        <div className="auth-glass-panel">
          <div className="auth-form-content auth-form-register">
            <AuthStepper steps={STEPS} currentStep={step} />

            <h1 className="doc-reg-title">{TITLES[step]}</h1>

            <form onSubmit={handleSubmit} noValidate>
              {step === 1 && (
                <div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-name">Full Name</label>
                    <input id="doc-name" className="auth-form-input" placeholder="e.g. Dr. Jane Perera" value={displayName} maxLength={120} autoComplete="name" onChange={(e) => setDisplayName(e.target.value)} />
                    {fieldError('displayName')}
                  </div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-email">Email Address</label>
                    <input id="doc-email" type="email" className="auth-form-input" placeholder="e.g. doctor@example.invalid" value={email} autoComplete="email" onChange={(e) => setEmail(e.target.value)} />
                    {fieldError('email')}
                  </div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-password">Password</label>
                    <div style={{ position: 'relative' }}>
                      <input id="doc-password" type={showPassword ? 'text' : 'password'} className="auth-form-input" style={{ paddingRight: '40px' }} placeholder="At least 12 characters" value={password} autoComplete="new-password" onChange={(e) => setPassword(e.target.value)} />
                      <PasswordEye show={showPassword} toggle={() => setShowPassword((v) => !v)} />
                    </div>
                    {fieldError('password')}
                  </div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-confirm">Confirm Password</label>
                    <div style={{ position: 'relative' }}>
                      <input id="doc-confirm" type={showPassword ? 'text' : 'password'} className="auth-form-input" style={{ paddingRight: '40px' }} placeholder="Confirm your password" value={confirm} autoComplete="new-password" onChange={(e) => setConfirm(e.target.value)} />
                      <PasswordEye show={showPassword} toggle={() => setShowPassword((v) => !v)} />
                    </div>
                    {fieldError('confirm')}
                  </div>
                </div>
              )}

              {step === 2 && (
                <div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-regno">SLMC Registration Number</label>
                    <input id="doc-regno" className="auth-form-input" placeholder="e.g. SLMC-9999" value={registrationNumber} maxLength={30} onChange={(e) => setRegistrationNumber(e.target.value)} />
                    {fieldError('registrationNumber')}
                  </div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-specialty">Specialization <em>(optional)</em></label>
                    <input id="doc-specialty" className="auth-form-input" placeholder="e.g. General Practice" value={specialty} maxLength={120} onChange={(e) => setSpecialty(e.target.value)} />
                    {fieldError('specialty')}
                  </div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-hospital">Hospital / Clinic <em>(optional)</em></label>
                    <input id="doc-hospital" className="auth-form-input" placeholder="e.g. City General Hospital" value={hospitalClinic} maxLength={200} onChange={(e) => setHospitalClinic(e.target.value)} />
                    {fieldError('hospitalClinic')}
                  </div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-phone">Professional Phone <em>(optional)</em></label>
                    <input id="doc-phone" type="tel" className="auth-form-input" placeholder="0771234567" value={phoneNumber} maxLength={20} autoComplete="tel" onChange={(e) => setPhoneNumber(e.target.value)} />
                    {fieldError('phoneNumber')}
                  </div>
                </div>
              )}

              {step === 3 && (
                <div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-city">Practice City</label>
                    <input id="doc-city" className="auth-form-input" value={practiceCity} maxLength={80} autoComplete="address-level2" onChange={(e) => setPracticeCity(e.target.value)} />
                    {fieldError('practiceCity')}
                  </div>
                  <div className="auth-form-group">
                    <label htmlFor="doc-district">District</label>
                    <select id="doc-district" className="auth-form-input" value={district} onChange={(e) => setDistrict(e.target.value)}>
                      <option value="">Select district</option>
                      {districts.map((item) => <option key={item} value={item}>{item}</option>)}
                    </select>
                    {fieldError('district')}
                  </div>
                  <fieldset className="auth-form-group doc-reg-fieldset">
                    <legend>Languages <em>(choose 1–3)</em></legend>
                    <div className="doc-reg-chips">
                      {languageOptions.map((language) => {
                        const checked = languages.includes(language)
                        return (
                          <label key={language} className={`doc-reg-chip ${checked ? 'selected' : ''}`}>
                            <input type="checkbox" checked={checked} onChange={() => setLanguages((current) => current.includes(language) ? current.filter((item) => item !== language) : [...current, language])} />
                            {language}
                          </label>
                        )
                      })}
                    </div>
                    {fieldError('languages')}
                  </fieldset>
                  <div className="auth-form-group">
                    <label htmlFor="doc-license">Licence Document <em>(PDF, PNG or JPEG · max 5 MB)</em></label>
                    <label htmlFor="doc-license" className="doc-reg-file">
                      <span className="doc-reg-file-btn">Choose file</span>
                      <span className="doc-reg-file-name">{licenseDocument?.name ?? 'No file chosen'}</span>
                    </label>
                    <input id="doc-license" type="file" className="doc-reg-file-input" accept="application/pdf,image/png,image/jpeg" onChange={(e) => setLicenseDocument(e.target.files?.[0] ?? null)} />
                    {fieldError('licenseDocument')}
                  </div>
                </div>
              )}

              {step === 4 && (
                <div>
                  <RegistrationReview
                    sections={reviewSections}
                    onEdit={(target) => { clearErrors(); setStep(target) }}
                    acceptTerms={acceptTerms}
                    onAcceptTermsChange={setAcceptTerms}
                    termsError={fieldError('acceptTerms')}
                  />
                  <div className="doc-reg-notice" role="note">
                    <strong>Verification required.</strong> Your profile will be reviewed by an administrator before clinical access is enabled.
                  </div>
                </div>
              )}

              {(apiError || authError) && <div role="alert" className="doc-reg-form-error">{apiError || authError}</div>}

              <div className="auth-btn-row">
                <button type="button" className="auth-btn-secondary" onClick={handleBack} disabled={isLoading}>Back</button>
                <button type="submit" className="auth-form-button" style={{ marginTop: 0 }} disabled={isLoading} aria-busy={isLoading}>
                  {isFinalStep ? (isLoading ? 'Submitting...' : 'Submit for Review') : step === 3 ? 'Review details' : 'Continue'}
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </main>
  )
}
